shots=[]
for si, scene in enumerate(scenes,1):
    title,act,loc,chars,purpose,start,action,end,audio,pbefore,pafter=scene
    phases=[
      (f"Establish {title} and its material circumstances.",start,f"The shot settles on {start}"),
      ("Make sincere kindness visible.",start,f"People respond gently while {action}"),
      ("Advance the scene's central contradiction.",action,f"Clearly show that {action}"),
      ("Reveal the consequence beneath the polite behavior.",action,f"Hold on the material consequence as {end}"),
      ("Register Mara's or the witnesses' emotional understanding.",end,f"A restrained reaction makes clear: {purpose}"),
      ("Create the visual and emotional handoff to the next scene.",end,f"End in a composed tableau: {end}")
    ]
    for pi,(beat,first_desc,last_desc) in enumerate(phases):
        order=(si-1)*6+pi+1
        sid=f"shot_{order:03d}"
        framing,angle,movement,lens=camera_cycle[pi]
        char_names=", ".join(next(c["name"] for c in bible["characters"] if c["id"]==cid) for cid in chars)
        prompt=(f"Standard MiniMax H3, five-second cinematic shot in the established Equal Shares visual style. "
                f"Location: {next(l['immutable_description'] for l in bible['locations'] if l['id']==loc)}. "
                f"Characters: {char_names}, preserving their exact story-bible appearance and wardrobe. "
                f"Start with {first_desc} Then {last_desc}. Camera: {framing}, {angle}, {movement}, {lens}. "
                f"Performance is sincere, restrained, and compassionate; nobody behaves cruelly. Maintain spatial, prop, wardrobe, and emotional continuity. {audio}")
        shots.append({
          "id":sid,"act":act,"scene":f"scene_{si:03d}_{title.lower().replace(' ','_').replace("'",'')}","sequence_order":order,"duration":5.0,
          "story_purpose":purpose,"required_story_beats":[beat],"characters_present":chars,"location":loc,"time_of_day":"continuous with scene",
          "wardrobe_state":{cid:"default_wardrobe" for cid in chars},"prop_state_before":pbefore if pi==0 else (pafter if pi>=3 else pbefore),"prop_state_after":pafter if pi>=2 else pbefore,
          "emotion_before":{cid:"restrained, attentive" for cid in chars},"emotion_after":{cid:"kind but more aware of the unresolved harm" for cid in chars},
          "screen_direction":"neutral; preserve established eyelines","camera":{"framing":framing,"angle":angle,"movement":movement,"lens_feel":lens},
          "first_frame":{"description":first_desc,"image_path":f"frames/{sid}_first.png","generation_prompt":f"Cinematic still, Equal Shares continuity. {char_names}. {first_desc}. {framing}, {angle}, warm restrained near-future realism, exact character and location continuity.","reuse_previous_last_frame":pi>0},
          "last_frame":{"description":last_desc,"image_path":f"frames/{sid}_last.png","generation_prompt":f"Cinematic still, Equal Shares continuity. {char_names}. {last_desc}. {framing}, {angle}, restrained social realism, exact character and prop continuity.","handoff_to_next":"Match emotional state, wardrobe, props, location geography, and screen direction into the following shot."},
          "video_prompt":prompt,"negative_prompt_additions":"melodramatic acting, hostility, smugness, obvious villain behavior, sitcom tone, abrupt unmotivated movement",
          "audio":{"dialogue":[],"ambience":audio,"sound_effects":[],"music":"minimal warm piano and low sustained tones, very subtle"},"seed":41000+order,"review_priority":"high" if si in {7,8,17,18,22,23,26,27,28,30} else "normal"
        })

plan={"schema_version":1,"story_bible":"story_bible.json","shots":shots}
(OUT/"story_bible.json").write_text(json.dumps(bible,indent=2,ensure_ascii=False),encoding="utf-8")
